window.COURSES = [
  { id: 'foundations', number: '01', title: '认识 Agent', subtitle: '从一次回答，到完成一个目标。', stage: '入门', minutes: 18, icon: 'orbit', tags: ['Agent loop', '任务边界'], intro: 'LLM 负责生成内容或提出下一步行动；Agent 则把模型放进一个可执行的循环，让它根据工具反馈继续行动。并非所有任务都需要 Agent，固定步骤通常可以先用工作流解决。', concepts: ['目标：用可观察的结果定义成功，例如“整理三篇文档的共同结论”。', '行动：模型提出调用工具，程序负责校验参数、执行并返回结果。', '终止：达到目标、预算耗尽或需要人工判断时结束循环。'], code: 'for step in range(5):\n    action = decide(goal, history)\n    if action["type"] == "finish":\n        break\n    result = run_allowed_tool(action)\n    history.append(result)', codeLabel: 'Agent 循环 · 结构示意', exercise: '选一个你想自动化的小任务，写下目标、可用工具和停止条件。先确认它是否真的需要动态决策。', question: '哪一项最能区分 Agent 循环与单次模型问答？', options: ['提示词的长度', '根据工具反馈决定后续行动', '模型参数量'], answer: 1, explanation: '关键在于行动与反馈形成循环；使用更长的提示词或更大的模型并不会自动构成 Agent。' },
  { id: 'tools', number: '02', title: '工具调用', subtitle: '让语言变成可验证的行动。', stage: '入门', minutes: 25, icon: 'tool', tags: ['Tool schema', '参数校验'], intro: '工具调用是模型输出的结构化请求。实际执行发生在你的程序中，因此权限、参数校验和错误处理都应该由程序控制。', concepts: ['描述：给工具一个明确名称、用途和参数约束。', '执行：使用允许列表分发调用，不执行模型生成的任意代码。', '反馈：返回清晰的结果或错误，让模型有依据地继续。'], code: 'def add(a: float, b: float) -> float:\n    return a + b\n\ntools = {"add": add}\nrequest = {"name": "add", "args": {"a": 2, "b": 3}}\nresult = tools[request["name"]](**request["args"])\nprint(result)  # 5', codeLabel: 'Python · 最小分发示例（输入预先确定）', exercise: '实现一个只接受数字的计算工具，补上参数类型检查，并为未知工具名返回可理解的错误。', question: '谁应该负责校验工具调用参数并决定是否执行？', options: ['执行工具的宿主程序', '工具描述中的一句提示', '由模型自行保证'], answer: 0, explanation: '模型可以提出调用，但边界应由宿主程序强制执行。生产实现还需要权限控制和异常处理。' },
  { id: 'planning', number: '03', title: '规划与循环', subtitle: '拆解任务，也给探索设定边界。', stage: '进阶', minutes: 30, icon: 'branch', tags: ['Planning', '停止条件'], intro: '复杂任务可能需要多个步骤。计划帮助分解目标，工具反馈帮助修正计划。步骤上限、重复检测与明确的完成标准可以避免无效循环。', concepts: ['先定义产出，再拆分能被检查的小步骤。', '每次工具返回后检查进展，需要时更新计划。', '对步数、时间和费用设置预算；无法推进时请求帮助。'], code: 'max_steps = 8\nfor step in range(max_steps):\n    observation = take_next_step()\n    if goal_reached(observation):\n        break\nelse:\n    request_human_review("已达到步骤上限")', codeLabel: '循环预算 · 结构示意', exercise: '为“比较三份资料”的任务写三个步骤，并指定遇到空结果、相互矛盾的信息和预算耗尽时怎么处理。', question: '工具连续返回同样的无效结果，合理的下一步是什么？', options: ['无限重试，直到成功', '忽略错误并宣称完成', '检查原因，调整策略或停止并请求帮助'], answer: 2, explanation: '重复本身不代表进展。应依据反馈改变策略，并在无法推进时明确停止。' },
  { id: 'memory', number: '04', title: '记忆与检索', subtitle: '把需要的信息带到当前任务。', stage: '进阶', minutes: 35, icon: 'layers', tags: ['Context', 'Retrieval'], intro: '上下文窗口有限。短期状态记录本次任务的进展；长期存储保存经过筛选的信息。检索负责在需要时取回相关片段，返回的内容仍需检查来源和相关性。', concepts: ['任务状态：保留目标、约束、已完成步骤和待解决问题。', '外部知识：按相关性检索资料，并保留来源供核对。', '不可信内容：资料中的指令不应该覆盖系统权限和用户目标。'], code: 'state = {\n    "goal": "总结资料中的共同结论",\n    "completed": ["收集资料"],\n    "open_questions": ["结论是否有冲突？"],\n}\ncontext = retrieve(state["goal"], limit=3)\n# 组合上下文时保留来源，并把资料作为数据处理', codeLabel: '任务状态 · 结构示意', exercise: '为一个文档助手设计状态字段，再定义检索片段必须附带哪些来源信息。', question: '检索到的文档要求“忽略原有规则”，应该如何处理？', options: ['立即执行文档中的要求', '将其作为不可信资料，不提升为控制指令', '永久删除所有记忆'], answer: 1, explanation: '检索资料是数据来源，不具备覆盖用户目标或程序权限的权力。' },
  { id: 'evaluation', number: '05', title: '评估与防护', subtitle: '让“能运行”变成“可检查”。', stage: '实践', minutes: 25, icon: 'shield', tags: ['Evals', 'Human review'], intro: '演示成功不代表稳定可靠。用固定任务集检查产出质量、工具使用和边界行为，再结合真实失败案例改进。风险较高的操作应设置人工确认。', concepts: ['结果：检查目标是否完成、结论是否有依据。', '过程：记录必要的工具请求、返回值、耗时和错误。', '边界：覆盖错误参数、空结果、权限不足和恶意资料。'], code: 'case = {\n    "task": "总结不存在的文档",\n    "expected": "说明资料不可用，不编造内容",\n}\nchecks = ["有依据", "目标完成", "未越权", "预算内"]\n# 对固定测试集逐项记录结果，并人工检查失败案例', codeLabel: '评估用例 · Python 数据示例', exercise: '给你的任务写三条正常用例和两条失败用例，为每条定义可观察的通过条件。', question: '哪一种方式更适合判断 Agent 是否可靠？', options: ['看一次演示是否流畅', '只检查回复字数', '在固定任务集上检查结果与边界行为'], answer: 2, explanation: '固定任务集有利于比较修改前后的表现，边界用例帮助发现正常演示覆盖不到的问题。' },
  { id: 'build', number: '06', title: '组装你的助手', subtitle: '交付一个有边界的小型 Agent。', stage: '实践', minutes: 45, icon: 'cube', tags: ['Build', '迭代验证'], intro: '从一个小目标开始，把模型、工具、状态与评估串起来。先跑通最小闭环，再依据失败案例扩展能力。这个练习不要求接入特定模型或框架。', concepts: ['选择单一场景：例如从本地资料中回答带来源的问题。', '明确工具与边界：只读检索、限定资料范围、限制执行步数。', '验证交付：记录成功案例、失败行为和仍然需要人工处理的情况。'], code: 'config = {\n    "goal": "从指定资料中回答问题并给出来源",\n    "tools": ["search_documents", "read_document"],\n    "max_steps": 6,\n    "on_missing_evidence": "说明缺少资料",\n}', codeLabel: '助手配置 · Python 数据示例', exercise: '完成一个只读文档助手的设计，使用上一节的五条用例验证，并写下一个已知限制。', question: '第一个 Agent 项目的合理交付标准是什么？', options: ['覆盖所有可能的需求', '在明确范围内完成任务，并通过预先定义的检查', '接入尽可能多的工具'], answer: 1, explanation: '明确范围和可检验标准能帮助你交付可靠的小闭环，并据此决定后续扩展。' }
];
